package com.example.maven;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugin.MojoFailureException;
import org.apache.maven.plugins.annotations.LifecyclePhase;
import org.apache.maven.plugins.annotations.Mojo;
import org.apache.maven.plugins.annotations.Parameter;

import java.util.Map;
import java.util.TreeMap;

@Mojo(
    name = "print-env",
    defaultPhase = LifecyclePhase.VALIDATE,
    requiresProject = false
)
public class EnvMojo extends AbstractMojo {

    @Parameter(property = "env.prefix", defaultValue = "")
    private String prefix;

    @Parameter(property = "env.maskValues", defaultValue = "false")
    private boolean maskValues;

    @Override
    public void execute() throws MojoExecutionException, MojoFailureException {

        Map<String, String> envVars = new TreeMap<>(System.getenv());

        String filterMsg = prefix.isEmpty()
                ? "all"
                : "variables starting with \"" + prefix + "\"";

        getLog().info("=== System Environment Variables (" + filterMsg + ") ===");

        int count = 0;
        for (Map.Entry<String, String> entry : envVars.entrySet()) {
            String name  = entry.getKey();
            String value = entry.getValue();

            if (!prefix.isEmpty() && !name.startsWith(prefix)) {
                continue;
            }

            String displayValue = maskValues ? "****" : value;
            getLog().info(String.format("  %-40s = %s", name, displayValue));
            count++;
        }

        getLog().info("=== Total: " + count + " variable(s) printed ===");
    }
}

